<!doctype html>
<html lang="ru">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow">
<title>4ДКУБ / ADMIN</title>
<style>
:root{--bg:#07090f;--panel:#0b0f17;--panel2:#101621;--field:#121925;--field2:#182131;--text:#eef1f7;--muted:#7f899a;--soft:#a8b0be;--danger:#ff9a9a;--shadow:0 18px 50px rgba(0,0,0,.22)}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:Arial,Helvetica,sans-serif}body{padding:86px 18px 18px}button,input,textarea,select{font:inherit;border:0;outline:0}button{cursor:pointer}.hidden{display:none!important}
.shell{max-width:1540px;margin:0 auto}.top{position:fixed;left:0;right:0;top:0;z-index:120;display:flex;align-items:center;justify-content:space-between;gap:18px;padding:12px max(18px,calc((100vw - 1540px)/2 + 18px));background:rgba(7,9,15,.94);backdrop-filter:blur(18px);box-shadow:0 10px 32px rgba(0,0,0,.18)}.brand{font-weight:800;letter-spacing:.18em}.muted{color:var(--muted);font-size:11px;letter-spacing:.1em;text-transform:uppercase}.statusline{font-size:11px;color:var(--muted);min-height:18px}
.top-nav{display:flex;align-items:center;gap:4px}.top-nav .nav-btn{width:auto;margin:0;white-space:nowrap;padding:10px 13px}.btn{background:#151c28;color:var(--text);padding:10px 14px;text-transform:uppercase;font-size:10px;letter-spacing:.1em;transition:background .16s ease,transform .16s ease,opacity .16s ease}.btn:hover{background:#202a3a}.btn:active{transform:translateY(1px)}.btn.primary{background:var(--text);color:#080a0f}.btn.primary:hover{background:#fff}.btn.danger{color:var(--danger);background:#21151a}.btn.ghost{background:transparent;color:var(--soft)}
.panel{background:var(--panel);box-shadow:var(--shadow)}.auth{max-width:460px;margin:12vh auto;padding:30px}.auth h1{font-size:24px;margin:0 0 8px}.note{font-size:12px;line-height:1.55;color:var(--muted)}.error{color:var(--danger);font-size:12px;margin:10px 0}
.field{display:grid;gap:7px;margin:0 0 14px}.field>label,.field-label{font-size:10px;text-transform:uppercase;letter-spacing:.1em;color:#8f98a8}.field input,.field textarea,.field select{width:100%;background:var(--field);color:var(--text);padding:11px 12px;transition:background .16s ease,box-shadow .16s ease}.field textarea{min-height:92px;resize:vertical}.field input:focus,.field textarea:focus,.field select:focus{background:var(--field2)}
.app-layout{display:block}.sidebar{display:none}.nav-btn{width:100%;text-align:left;padding:13px 14px;margin:2px 0;background:transparent;color:var(--muted);text-transform:uppercase;letter-spacing:.1em;font-size:10px}.nav-btn:hover{background:#111824;color:var(--text)}.nav-btn.active{background:var(--text);color:#07090f}.workspace{display:none}.workspace.active{display:block}.section{padding:20px;margin-bottom:16px}.section h2{font-size:15px;margin:0 0 16px;letter-spacing:.08em;text-transform:uppercase}.section-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:18px}.section-head h2{margin:0}.section-head p{margin:4px 0 0}
.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.rowcard{padding:15px;background:#0d121b}.rowcard h3{font-size:11px;margin:0 0 12px;color:#d4dae4;text-transform:uppercase;letter-spacing:.1em}.rowcard+.rowcard{margin-top:10px}.item-grid{display:grid;grid-template-columns:75px 1fr 2fr;gap:8px}.item-grid+.item-grid{margin-top:8px}.service-detail-card{background:#090d14;padding:14px;margin-top:10px}.service-detail-card h4{margin:0 0 10px;font-size:10px;letter-spacing:.09em;text-transform:uppercase;color:#d7dde8}.service-detail-card textarea{min-height:120px}.service-questions{min-height:170px!important}.subtle{font-size:10px;line-height:1.45;color:#70798b}
.savebar{position:sticky;bottom:12px;display:flex;justify-content:flex-end;align-items:center;gap:10px;padding:10px 0}.project-layout{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(390px,.95fr);gap:16px}.project-list{padding:10px}.project-item{display:grid;grid-template-columns:64px minmax(0,1fr) 130px 58px;gap:12px;align-items:center;padding:10px;background:#0b1018;margin-bottom:6px;cursor:pointer;transition:background .15s ease,transform .15s ease}.project-item:hover{background:#121a26;transform:translateX(2px)}.project-item.active{background:#192334}.thumb{width:64px;height:44px;object-fit:cover;background:#161b26}.project-title{font-size:12px}.project-cat,.project-state{font-size:10px;color:#8992a4;text-transform:uppercase}.editor{padding:20px;position:sticky;top:18px;align-self:start}.preview{width:100%;aspect-ratio:4/3;object-fit:cover;background:#141924;margin-bottom:14px}.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.sep{height:10px}.checkbox{display:flex;align-items:center;gap:9px;color:#cdd3df;font-size:12px}.checkbox input{width:17px;height:17px;accent-color:#eef1f7}.small{font-size:11px}
.design-layout{display:block}.design-controls{display:grid;gap:16px;max-width:1040px}.font-preview{padding:22px;background:#111824;font-size:23px;line-height:1.35;min-height:120px}.control-row{display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center}.control-row output{font-size:11px;color:var(--soft);min-width:62px;text-align:right}.field input[type=range]{padding:0;background:transparent;accent-color:#eef1f7}.scope-note{background:#111824;padding:12px;color:var(--soft);font-size:11px;line-height:1.5}.preview-drawer{position:fixed;left:0;right:0;top:64px;z-index:110;display:none;padding:14px 18px 18px;background:rgba(7,9,15,.97);backdrop-filter:blur(18px);box-shadow:0 24px 50px rgba(0,0,0,.38)}.preview-drawer.open{display:block}.preview-drawer__inner{max-width:1540px;margin:0 auto}.preview-toolbar{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:0 0 10px}.preview-toolbar__actions{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.preview-mode{background:#101621;color:var(--muted);padding:9px 12px;text-transform:uppercase;font-size:9px;letter-spacing:.1em}.preview-mode.active{background:var(--text);color:#07090f}.preview-stage{display:flex;justify-content:center;align-items:flex-start;max-height:calc(100vh - 148px);overflow:auto;background:#05070b;padding:10px}.preview-frame-wrap{width:min(100%,1365px);aspect-ratio:16/9;background:#05070b;transition:width .2s ease,aspect-ratio .2s ease}.preview-frame-wrap.mobile{width:min(390px,100%);aspect-ratio:390/844}.site-preview{display:block;width:100%;height:100%;background:#05070b}
@media(max-width:1050px){.project-layout{grid-template-columns:1fr}.editor{position:static}.grid,.grid3{grid-template-columns:1fr}.project-item{grid-template-columns:54px minmax(0,1fr) 58px}.project-cat{display:none}.top{overflow-x:auto}.top>*{flex:0 0 auto}}
@media(max-width:620px){body{padding:76px 10px 10px}.top{padding:10px;gap:10px}.brand{font-size:12px}.top .muted{display:none}.top-nav{gap:2px}.top-nav .nav-btn{padding:9px 10px}.section{padding:14px}.project-item{grid-template-columns:48px 1fr}.project-state:last-child{display:none}.item-grid{grid-template-columns:56px 1fr}.item-grid input:last-child{grid-column:1/-1}.preview-drawer{top:54px;padding:10px}.preview-stage{padding:4px;max-height:calc(100vh - 120px)}}

/* v10.6 multi-media case manager */
.media-manager{margin-top:18px;padding:16px;background:#090d14}.media-manager__head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:12px}.media-manager__head h3{margin:0;font-size:11px;letter-spacing:.1em;text-transform:uppercase}.media-list{display:grid;gap:7px}.media-item{display:grid;grid-template-columns:20px 74px minmax(0,1fr) auto;gap:10px;align-items:center;padding:9px;background:#101621;cursor:grab}.media-item.dragging{opacity:.45}.media-item__handle{color:#677184;font-size:15px;text-align:center;user-select:none}.media-thumb{width:74px;height:50px;object-fit:cover;background:#171e2b}.media-thumb.video{object-fit:cover}.media-meta{min-width:0}.media-path{font-size:10px;color:#aeb6c4;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.media-kind{font-size:9px;letter-spacing:.1em;text-transform:uppercase;color:#697386;margin-top:4px}.media-actions{display:flex;gap:5px;align-items:center;flex-wrap:wrap;justify-content:flex-end}.media-actions .btn{padding:8px 9px;font-size:8px}.media-actions .cover-active{background:#edf1f7;color:#080a0f}.media-empty{padding:20px;background:#0d121b;color:#697386;font-size:11px;text-align:center}.media-help{margin-top:10px;color:#697386;font-size:10px;line-height:1.5}.preview-video{width:100%;aspect-ratio:4/3;object-fit:cover;background:#141924;margin-bottom:14px}.preview.hidden-preview{display:none}.preview-video.hidden-preview{display:none}.upload-progress{color:#aeb6c4;font-size:10px}
@media(max-width:620px){.media-item{grid-template-columns:18px 58px 1fr}.media-thumb{width:58px;height:42px}.media-actions{grid-column:2/-1;justify-content:flex-start}}
</style>
</head>
<body>
<div class="shell">
  <div class="top">
    <div><div class="brand">4ДКУБ / ADMIN</div><div class="muted">Content · Projects · Design</div></div>
    <nav id="topNav" class="actions top-nav hidden"><button class="nav-btn active" data-tab="texts">Контент</button><button class="nav-btn" data-tab="projects">Кейсы</button><button class="nav-btn" data-tab="design">Дизайн</button></nav>
    <div class="actions"><span id="topStatus" class="statusline"></span><button id="previewToggle" class="btn hidden">Предпросмотр</button><button id="openSiteBtn" class="btn hidden">Открыть сайт</button><button id="clearCacheBtn" class="btn hidden">Очистить кэш</button><button id="logoutBtn" class="btn hidden">Выйти</button></div>
  </div>

  <div id="authBox" class="panel auth hidden">
    <h1 id="authTitle">Вход</h1><p id="authText" class="note"></p>
    <div class="field"><label>Пароль</label><input id="password" type="password" autocomplete="current-password"></div>
    <div id="authError" class="error"></div><button id="authSubmit" class="btn primary">Продолжить</button>
  </div>

  <div id="app" class="hidden app-layout">
    <main>
      <div id="texts" class="workspace active">
        <div class="panel section"><div class="section-head"><div><h2>Внешние разделы</h2><p class="note">Заголовки и тексты экранов вокруг куба.</p></div></div><div id="statesEditor" class="grid"></div></div>
        <div class="panel section"><div class="section-head"><div><h2>Внутренние разделы</h2><p class="note">Подписи граней и контент внутри куба.</p></div></div><div id="sectionsEditor"></div></div>
        <div class="savebar"><span id="contentStatus" class="statusline"></span><button id="saveContent" class="btn primary">Сохранить контент</button></div>
      </div>

      <div id="projects" class="workspace">
        <div class="project-layout">
          <div class="panel project-list"><div class="actions" style="justify-content:space-between;padding:8px 8px 14px"><div><div class="muted">Портфолио</div><div class="note">Клик по кейсу открывает редактор.</div></div><div class="actions"><select id="projectSort" class="btn" aria-label="Сортировка кейсов"><option value="newest">Сначала новые</option><option value="oldest">Сначала старые</option><option value="az">А–Я</option><option value="za">Я–А</option></select><button id="newProject" class="btn">+ Новый кейс</button></div></div><div id="projectList"></div></div>
          <div class="panel editor">
            <div class="muted" style="margin-bottom:12px">Редактор кейса</div>
            <img id="projectPreview" class="preview" alt="">
            <video id="projectVideoPreview" class="preview-video hidden-preview" muted loop playsinline controls></video>
            <input id="projectId" type="hidden">
            <div class="field"><label>Название</label><input id="projectTitle"></div>
            <div class="grid3"><div class="field"><label>Рубрика</label><select id="projectCategory"><option value="0">Сайты</option><option value="1">Айдентика</option><option value="2">Интерфейсы</option><option value="3">Видео</option><option value="4">Полиграфия</option><option value="5">Мерч</option></select></div><div class="field"><label>Год</label><input id="projectYear" placeholder="2026"></div><div class="field"><label>Порядок</label><input id="projectOrder" type="number" value="10"></div></div>
            <div class="field"><label>Описание / fallback задачи</label><textarea id="projectDescription"></textarea></div>
            <div class="grid"><div class="field"><label>Клиент</label><input id="projectClient"></div><div class="field"><label>CTA текст</label><input id="projectCtaText"></div></div>
            <div class="field"><label>Задача</label><textarea id="projectTask"></textarea></div>
            <div class="field"><label>Решение</label><textarea id="projectSolution"></textarea></div>
            <div class="field"><label>Реализация</label><textarea id="projectImplementation"></textarea></div>
            <div class="field"><label>Технологии — через запятую</label><input id="projectTechnologies"></div>
            <div class="field"><label>CTA ссылка</label><input id="projectCtaLink"></div>
            <input id="projectImage" type="hidden">
            <section class="media-manager">
              <div class="media-manager__head"><div><h3>Медиа кейса</h3><div class="note">Фото и видео показываются внутри кейса в этом порядке.</div></div><button id="uploadBtn" class="btn">+ Добавить медиа</button></div>
              <input id="projectFile" type="file" multiple accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm" class="hidden">
              <div id="mediaList" class="media-list"></div>
              <div class="media-help">Перетащите элементы для изменения порядка. «Обложка» используется в списке проектов. Изменения порядка и обложки существующего кейса сохраняются сразу.</div>
              <div id="uploadStatus" class="statusline upload-progress"></div>
            </section>
            <div class="sep"></div><label class="checkbox"><input id="projectPublished" type="checkbox" checked> Опубликован</label><div class="sep"></div>
            <div class="actions"><button id="applyProject" class="btn primary">Применить в списке</button><button id="deleteProject" class="btn danger">Удалить кейс</button></div>
          </div>
        </div>
        <div class="savebar"><span id="projectsStatus" class="statusline"></span><button id="saveProjects" class="btn primary">Сохранить портфолио</button></div>
      </div>

      <div id="design" class="workspace">
        <div class="design-layout">
          <div class="design-controls">
            <section class="panel section">
              <div class="section-head"><div><h2>Шрифты</h2><p class="note">Интерфейсный шрифт также применяется к подписям на гранях куба.</p></div></div>
              <div class="grid3"><div class="field"><label>Основной</label><select id="mainFont"></select></div><div class="field"><label>Заголовки</label><select id="headingFont"></select></div><div class="field"><label>Интерфейс + куб</label><select id="uiFont"></select></div></div>
              <div id="fontPreview" class="font-preview">4ДКУБ / Проекты / Identity 0123<br>Съешь ещё этих мягких французских булок</div>
            </section>
            <section class="panel section">
              <div class="section-head"><div><h2>Фон и куб</h2><p class="note">Изменения сразу отправляются в предпросмотр справа. Сохраняются только по кнопке ниже.</p></div></div>
              <div class="field"><label>Фон</label><select id="backgroundTheme"><option value="0">Базовый тёмный</option><option value="1">Светлый</option><option value="2">Почти белый</option><option value="3">Серо-синий</option><option value="4">Фиолетовый</option><option value="5">Без тёмных краёв</option><option value="6">Без виньетки</option><option value="7">Яркий центр</option><option value="8">Цветные пятна</option><option value="9">Другое движение</option></select></div>
              <div class="field"><div class="control-row"><label>Яркость фона</label><output id="backgroundIntensityOut">1.00</output></div><input id="backgroundIntensity" type="range" min="0.35" max="1.8" step="0.05"></div>
              <div class="field"><div class="control-row"><label>Прозрачность граней</label><output id="cubeOpacityOut">0.20</output></div><input id="cubeOpacity" type="range" min="0.03" max="0.65" step="0.01"></div>
              <div class="field"><div class="control-row"><label>Скорость гиперкуба</label><output id="hyperSpeedOut">1.00</output></div><input id="hyperSpeed" type="range" min="0.05" max="3" step="0.05"></div>
            </section>
            <section class="panel section">
              <div class="section-head"><div><h2>Типографика экранов</h2><p class="note">Настройки можно задать отдельно для главной, внешних экранов, внутренних разделов и страницы кейса.</p></div></div>
              <div class="field"><label>Экран</label><select id="typographyScope"></select></div>
              <div id="typographyScopeNote" class="scope-note"></div>
              <div class="field"><div class="control-row"><label>Размер заголовков</label><output id="headingSizeOut">48 px</output></div><input id="headingSize" type="range" min="16" max="120" step="1"></div>
              <div class="field"><div class="control-row"><label>Размер текста</label><output id="bodySizeOut">14 px</output></div><input id="bodySize" type="range" min="8" max="40" step="1"></div>
              <div class="field"><div class="control-row"><label>Межстрочный интервал</label><output id="lineHeightOut">1.35</output></div><input id="lineHeight" type="range" min="0.85" max="2.4" step="0.05"></div>
              <div class="field"><div class="control-row"><label>Межбуквенный интервал</label><output id="letterSpacingOut">0.00 em</output></div><input id="letterSpacing" type="range" min="-0.08" max="0.30" step="0.01"></div>
              <div class="field"><label>Выравнивание</label><select id="textAlign"><option value="left">Слева</option><option value="center">По центру</option><option value="right">Справа</option></select></div>
              <button id="resetTypography" class="btn">Сбросить этот экран</button>
            </section>
            <div class="savebar"><span id="designStatus" class="statusline"></span><button id="saveDesign" class="btn primary">Сохранить дизайн</button></div>
          </div>
        </div>
      </div>
    </main>
  </div>
  <div id="previewDrawer" class="preview-drawer">
    <div class="preview-drawer__inner">
      <div class="preview-toolbar"><div><div class="muted">Живой предпросмотр</div><div class="note">Desktop 16:9 или реальная мобильная ширина.</div></div><div class="preview-toolbar__actions"><button class="preview-mode active" data-preview-mode="desktop">Desktop</button><button class="preview-mode" data-preview-mode="mobile">Mobile</button><button id="reloadPreview" class="btn">Обновить</button><button id="closePreview" class="btn">Закрыть</button></div></div>
      <div class="preview-stage"><div id="previewFrameWrap" class="preview-frame-wrap"><iframe id="sitePreview" class="site-preview" src="/?adminPreview=1" title="Предпросмотр сайта"></iframe></div></div>
    </div>
  </div>
</div>
<script>
const API='/api/admin.php';let csrf='';let content=null;let projects=[];let editingIndex=-1;let projectSort='newest';let projectMediaDraft=[];let draggedMediaIndex=-1;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
async function api(action,options={}){const headers={...(options.headers||{})};if(csrf)headers['X-CSRF-Token']=csrf;const r=await fetch(`${API}?action=${encodeURIComponent(action)}`,{cache:'no-store',credentials:'same-origin',...options,headers});const raw=await r.text();let j;try{j=raw?JSON.parse(raw):{};}catch(_){const clean=raw.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim().slice(0,240);throw new Error(`HTTP_${r.status}: ${clean||'EMPTY_RESPONSE'}`)}if(!r.ok||!j.ok){const detail=j.hint?` — ${j.hint}`:'';throw new Error((j.error||`HTTP_${r.status}`)+detail)}if(j.csrf)csrf=j.csrf;return j}
function formJson(data){const body=new URLSearchParams();body.set('payload',JSON.stringify(data));return{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:body.toString()}}
function authError(e){const map={PASSWORD_TOO_SHORT:'Минимум 8 символов.',WRONG_PASSWORD:'Неверный пароль.',CONFIG_WRITE_FAILED:'Не удалось создать конфигурацию. Проверь права на public/api.',WRITE_FAILED:'Не удалось записать JSON. Проверь права на public/data.',UPLOAD_DIR_NOT_WRITABLE:'Нет прав на запись в папку загрузок.'};return map[e.message]||e.message}
async function boot(){try{const s=await api('status');if(!s.configured)return showAuth('setup');if(!s.authenticated)return showAuth('login');csrf=s.csrf||'';await loadApp()}catch(e){showAuth('login');$('#authError').textContent=authError(e)}}
function showAuth(mode){$('#authBox').classList.remove('hidden');$('#app').classList.add('hidden');$('#logoutBtn').classList.add('hidden');$('#openSiteBtn').classList.add('hidden');$('#clearCacheBtn').classList.add('hidden');$('#previewToggle').classList.add('hidden');$('#topNav').classList.add('hidden');$('#authTitle').textContent=mode==='setup'?'Первый запуск':'Вход';$('#authText').textContent=mode==='setup'?'Задайте пароль администратора. Он сохранится на сервере.':'Введите пароль администратора.';$('#authSubmit').dataset.mode=mode}
$('#authSubmit').onclick=async()=>{const mode=$('#authSubmit').dataset.mode;$('#authError').textContent='';try{const j=await api(mode,formJson({password:$('#password').value}));csrf=j.csrf||csrf;$('#password').value='';await loadApp()}catch(e){$('#authError').textContent=authError(e)}};
$('#password').addEventListener('keydown',e=>{if(e.key==='Enter')$('#authSubmit').click()});
async function loadApp(){const j=await api('load');content=j.content||{};projects=j.projects||[];$('#authBox').classList.add('hidden');$('#app').classList.remove('hidden');$('#logoutBtn').classList.remove('hidden');$('#openSiteBtn').classList.remove('hidden');$('#clearCacheBtn').classList.remove('hidden');$('#previewToggle').classList.remove('hidden');$('#topNav').classList.remove('hidden');renderContent();renderProjects();const first=sortedProjectEntries()[0];if(first)editProject(first.i);else newProject();renderDesign()}
$('#logoutBtn').onclick=async()=>{try{await api('logout',{method:'POST'});csrf='';location.reload()}catch(e){alert(authError(e))}};
$('#openSiteBtn').onclick=()=>window.open('/','_blank','noopener');
$('#clearCacheBtn').onclick=async()=>{const st=$('#topStatus');st.textContent='Очистка кэша…';try{await api('clear_cache',{method:'POST'});st.textContent='Кэш очищен';setTimeout(()=>{if(st.textContent==='Кэш очищен')st.textContent=''},2200)}catch(e){st.textContent=authError(e)}};
$$('[data-tab]').forEach(b=>b.onclick=()=>{$$('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));$$('.workspace').forEach(w=>w.classList.toggle('active',w.id===b.dataset.tab));if(b.dataset.tab==='projects'&&editingIndex<0&&projects.length)editProject(0);if(b.dataset.tab==='design')sendDesignPreview()});

function renderContent(){
  const stateNames=['Главная','Услуги','Проекты','Компания','Лаборатория','Магазин','Контакты'];
  $('#statesEditor').innerHTML=(content.states||[]).map((s,i)=>`<div class="rowcard" data-state="${i}"><h3>${stateNames[i]||`Раздел ${i+1}`}</h3><div class="field"><label>Название в меню</label><input data-k="nav" value="${esc(s.nav)}"></div><div class="field"><label>Заголовок</label><input data-k="title" value="${esc(s.title)}"></div><div class="field"><label>Описание</label><textarea data-k="description">${esc(s.description)}</textarea></div><div class="field"><label>Status</label><input data-k="status" value="${esc(s.status)}"></div></div>`).join('');
  const order=['services','projects','company','lab','shop','contacts'];
  $('#sectionsEditor').innerHTML=order.map(key=>{const s=content.sections?.[key];if(!s)return'';const items=(s.items||[]).map((it,idx)=>{const base=`<div class="item-grid" data-item="${idx}"><input data-ik="number" value="${esc(it.number)}"><input data-ik="title" value="${esc(it.title)}"><input data-ik="short" value="${esc(it.short)}"></div>`;if(key!=='services')return base;const questions=Array.isArray(it.questions)?it.questions.join('\n'):'';return `${base}<div class="service-detail-card" data-service-detail="${idx}"><h4>${esc(it.title||('Услуга '+(idx+1)))} / текст внутри куба</h4><div class="field"><label>Вступительный текст</label><textarea data-dk="lead">${esc(it.lead||'')}</textarea></div><div class="field"><label>Вопросы / пункты — по одному на строку</label><textarea class="service-questions" data-dk="questions">${esc(questions)}</textarea></div><div class="field"><label>Заключительный текст</label><textarea data-dk="outro">${esc(it.outro||'')}</textarea></div><div class="grid"><div class="field"><label>Текст кнопки</label><input data-dk="cta" value="${esc(it.cta||'')}"></div><div class="field"><label>Примечание</label><div class="subtle">Пустое поле не выводится на сайте.</div></div></div></div>`}).join('');return `<div class="rowcard" data-section="${key}"><h3>${esc(s.title)} / ${key}</h3><div class="grid3"><div class="field"><label>Название</label><input data-sk="title" value="${esc(s.title)}"></div><div class="field"><label>Подпись снаружи</label><input data-sk="eyebrow" value="${esc(s.eyebrow)}"></div><div class="field"><label>Подпись внутри</label><input data-sk="innerLabel" value="${esc(s.innerLabel)}"></div></div><div class="muted" style="margin:6px 0 8px">Пункты</div>${items}</div>`}).join('')
}
function collectContent(){
  $$('[data-state]').forEach(card=>{const i=+card.dataset.state;card.querySelectorAll('[data-k]').forEach(el=>content.states[i][el.dataset.k]=el.value)});
  $$('[data-section]').forEach(card=>{const s=content.sections[card.dataset.section];card.querySelectorAll('[data-sk]').forEach(el=>s[el.dataset.sk]=el.value);card.querySelectorAll('[data-item]').forEach(row=>{const idx=+row.dataset.item;const it=s.items[idx];row.querySelectorAll('[data-ik]').forEach(el=>it[el.dataset.ik]=el.value);if(card.dataset.section==='services'){const detail=card.querySelector(`[data-service-detail="${idx}"]`);if(detail)detail.querySelectorAll('[data-dk]').forEach(el=>{if(el.dataset.dk==='questions')it.questions=el.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);else it[el.dataset.dk]=el.value})}})});return content
}
$('#saveContent').onclick=async()=>{const st=$('#contentStatus');st.textContent='Сохранение…';try{await api('save_content',formJson(collectContent()));st.textContent='Сохранено'}catch(e){st.textContent=authError(e)}};

const catNames=['Сайты','Айдентика','Интерфейсы','Видео','Полиграфия','Мерч'];
function sortedProjectEntries(){const rows=projects.map((p,i)=>({p,i}));const year=n=>{const y=parseInt(n?.year,10);return Number.isFinite(y)?y:0};const title=n=>String(n?.title||'').localeCompare('', 'ru');if(projectSort==='newest')rows.sort((a,b)=>year(b.p)-year(a.p)||b.i-a.i);else if(projectSort==='oldest')rows.sort((a,b)=>year(a.p)-year(b.p)||a.i-b.i);else if(projectSort==='az')rows.sort((a,b)=>String(a.p.title||'').localeCompare(String(b.p.title||''),'ru',{sensitivity:'base'}));else if(projectSort==='za')rows.sort((a,b)=>String(b.p.title||'').localeCompare(String(a.p.title||''),'ru',{sensitivity:'base'}));return rows}
function isVideoPath(src){return /\.(mp4|webm)(?:\?|#|$)/i.test(String(src||''))}
function normalizeMedia(p){let rows=Array.isArray(p?.media)?p.media:[];rows=rows.map((m,i)=>{if(typeof m==='string')return{id:`media-${i}`,src:m,type:isVideoPath(m)?'video':'image',cover:i===0};if(!m||typeof m!=='object')return null;const src=String(m.src||m.path||m.url||'');if(!src)return null;return{id:String(m.id||`media-${i}`),src,type:m.type==='video'||isVideoPath(src)?'video':'image',cover:m.cover===true,alt:String(m.alt||'')}}).filter(Boolean);if(!rows.length&&p?.image){rows=[{id:'legacy-cover',src:String(p.image),type:isVideoPath(p.image)?'video':'image',cover:true,alt:String(p.title||'')}]};if(rows.length&&!rows.some(m=>m.cover))rows[0].cover=true;return rows}
function mediaCover(rows=projectMediaDraft){return rows.find(m=>m.cover)||rows[0]||null}
function syncProjectPreview(){const cover=mediaCover();const img=$('#projectPreview'),video=$('#projectVideoPreview');if(!cover){img.src='';img.classList.remove('hidden-preview');video.pause();video.removeAttribute('src');video.classList.add('hidden-preview');return}if(cover.type==='video'||isVideoPath(cover.src)){img.classList.add('hidden-preview');video.src=cover.src;video.classList.remove('hidden-preview');video.load()}else{video.pause();video.removeAttribute('src');video.classList.add('hidden-preview');img.src=cover.src;img.classList.remove('hidden-preview')}$('#projectImage').value=cover.src||''}
function renderMediaList(){const box=$('#mediaList');if(!projectMediaDraft.length){box.innerHTML='<div class="media-empty">Медиа пока нет. Добавьте изображение или видео.</div>';syncProjectPreview();return}box.innerHTML=projectMediaDraft.map((m,i)=>`<div class="media-item" draggable="true" data-mi="${i}"><div class="media-item__handle">⋮⋮</div>${m.type==='video'?`<video class="media-thumb video" src="${esc(m.src)}" muted playsinline preload="metadata"></video>`:`<img class="media-thumb" src="${esc(m.src)}" alt="">`}<div class="media-meta"><div class="media-path">${esc(m.src)}</div><div class="media-kind">${m.type==='video'?'VIDEO':'IMAGE'}${m.cover?' · ОБЛОЖКА':''}</div></div><div class="media-actions"><button class="btn ${m.cover?'cover-active':''}" type="button" data-cover-media="${i}">${m.cover?'Обложка ✓':'Сделать обложкой'}</button><button class="btn danger" type="button" data-delete-media="${i}">Удалить</button></div></div>`).join('');
  box.querySelectorAll('.media-item').forEach(el=>{el.ondragstart=()=>{draggedMediaIndex=+el.dataset.mi;el.classList.add('dragging')};el.ondragend=()=>{draggedMediaIndex=-1;el.classList.remove('dragging')};el.ondragover=e=>e.preventDefault();el.ondrop=async e=>{e.preventDefault();const to=+el.dataset.mi;if(draggedMediaIndex<0||to===draggedMediaIndex)return;const moved=projectMediaDraft.splice(draggedMediaIndex,1)[0];projectMediaDraft.splice(to,0,moved);draggedMediaIndex=-1;renderMediaList();await persistMediaDraft('Порядок сохранён')}});
  $$('[data-cover-media]').forEach(b=>b.onclick=async()=>{const i=+b.dataset.coverMedia;projectMediaDraft.forEach((m,x)=>m.cover=x===i);renderMediaList();await persistMediaDraft('Обложка сохранена')});
  $$('[data-delete-media]').forEach(b=>b.onclick=async()=>{const i=+b.dataset.deleteMedia;if(!confirm('Убрать этот файл из кейса? Сам файл на сервере удалён не будет.'))return;projectMediaDraft.splice(i,1);if(projectMediaDraft.length&&!projectMediaDraft.some(m=>m.cover))projectMediaDraft[0].cover=true;renderMediaList();await persistMediaDraft('Медиа удалено из кейса')});
  syncProjectPreview()
}
async function persistMediaDraft(successText='Медиа сохранено'){if(editingIndex<0||!projects[editingIndex]?.id)return;const st=$('#uploadStatus');st.textContent='Сохранение медиа…';try{const j=await api('update_project_media',formJson({project_id:projects[editingIndex].id,media:projectMediaDraft}));projects[editingIndex]=j.project;projectMediaDraft=normalizeMedia(j.project);renderProjects();syncProjectPreview();st.textContent=successText}catch(e){st.textContent=authError(e)}}
function renderProjects(){const rows=sortedProjectEntries();$('#projectList').innerHTML=rows.map(({p,i})=>{const cover=normalizeMedia(p).find(m=>m.cover)||normalizeMedia(p)[0];const thumb=cover?.src||p.image||'/favicon.svg';return`<div class="project-item${i===editingIndex?' active':''}" data-pi="${i}">${isVideoPath(thumb)?`<video class="thumb" src="${esc(thumb)}" muted playsinline preload="metadata"></video>`:`<img class="thumb" src="${esc(thumb)}" alt="">`}<div><div class="project-title">${esc(p.title)}</div><div class="project-state">${p.year?esc(p.year)+' · ':''}${p.published?'опубликован':'скрыт'} · ${normalizeMedia(p).length} медиа</div></div><div class="project-cat">${catNames[p.category]||''}</div><div class="project-state">${p.order||0}</div></div>`}).join('');$$('[data-pi]').forEach(el=>el.onclick=()=>editProject(+el.dataset.pi))}
function fillProject(p){$('#projectId').value=p.id||'';$('#projectTitle').value=p.title||'';$('#projectCategory').value=String(p.category??0);$('#projectYear').value=p.year||'';$('#projectOrder').value=p.order??10;$('#projectDescription').value=p.description||'';$('#projectClient').value=p.client||'';$('#projectTask').value=p.task||p.description||'';$('#projectSolution').value=p.solution||'';$('#projectImplementation').value=p.implementation||'';$('#projectTechnologies').value=Array.isArray(p.technologies)?p.technologies.join(', '):'';$('#projectCtaText').value=p.ctaText||'';$('#projectCtaLink').value=p.ctaLink||'';$('#projectPublished').checked=p.published!==false;projectMediaDraft=normalizeMedia(p);renderMediaList()}
function editProject(i){editingIndex=i;fillProject(projects[i]);renderProjects()}
function newProject(){editingIndex=-1;fillProject({id:'',title:'',category:0,year:'',order:10,description:'',client:'',task:'',solution:'',implementation:'',technologies:[],ctaText:'',ctaLink:'',image:'',media:[],published:true});renderProjects()}
function readProjectForm(){const cover=mediaCover();return{id:$('#projectId').value||('project-'+Date.now()),title:$('#projectTitle').value.trim(),category:+$('#projectCategory').value,year:$('#projectYear').value.trim(),order:+$('#projectOrder').value||0,description:$('#projectDescription').value.trim(),client:$('#projectClient').value.trim(),task:$('#projectTask').value.trim(),solution:$('#projectSolution').value.trim(),implementation:$('#projectImplementation').value.trim(),technologies:$('#projectTechnologies').value.split(',').map(v=>v.trim()).filter(Boolean),ctaText:$('#projectCtaText').value.trim(),ctaLink:$('#projectCtaLink').value.trim(),image:cover?.src||'',media:projectMediaDraft.map(m=>({...m})),published:$('#projectPublished').checked}}
$('#newProject').onclick=newProject;$('#projectSort').onchange=()=>{projectSort=$('#projectSort').value;renderProjects();const rows=sortedProjectEntries();if(rows.length&&editingIndex<0)editProject(rows[0].i)};
$('#applyProject').onclick=()=>{const p=readProjectForm();if(!p.title)return alert('Введите название проекта');if(editingIndex<0){projects.push(p);editingIndex=projects.length-1}else projects[editingIndex]=p;renderProjects();const idx=projects.findIndex(x=>x.id===p.id);if(idx>=0)editProject(idx)};
$('#deleteProject').onclick=()=>{if(editingIndex<0)return newProject();if(!confirm('Удалить кейс из портфолио? Загруженные файлы останутся на сервере.'))return;projects.splice(editingIndex,1);renderProjects();const rows=sortedProjectEntries();if(rows.length)editProject(rows[0].i);else newProject()};
$('#saveProjects').onclick=async()=>{const st=$('#projectsStatus');st.textContent='Сохранение…';try{if($('#projectTitle').value.trim()){const p=readProjectForm();if(editingIndex<0){projects.push(p);editingIndex=projects.length-1}else projects[editingIndex]=p}const j=await api('save_projects',formJson({projects}));projects=j.projects||projects;renderProjects();if(projects.length){editingIndex=Math.max(0,Math.min(editingIndex,projects.length-1));editProject(editingIndex)}st.textContent='Сохранено'}catch(e){st.textContent=authError(e)}};
$('#uploadBtn').onclick=()=>$('#projectFile').click();
$('#projectFile').onchange=async()=>{const files=[...$('#projectFile').files];if(!files.length)return;const st=$('#uploadStatus');try{for(let n=0;n<files.length;n++){const f=files[n];st.textContent=`Загрузка ${n+1} / ${files.length}…`;if(editingIndex>=0&&projects[editingIndex]?.id){const fd=new FormData();fd.append('file',f);fd.append('project_id',projects[editingIndex].id);const j=await api('add_project_media',{method:'POST',body:fd});projects[editingIndex]=j.project;projectMediaDraft=normalizeMedia(j.project)}else{const fd=new FormData();fd.append('file',f);const j=await api('upload',{method:'POST',body:fd});projectMediaDraft.push({id:`media-${Date.now()}-${n}`,src:j.path,type:isVideoPath(j.path)?'video':'image',cover:projectMediaDraft.length===0})}}renderMediaList();renderProjects();st.textContent=editingIndex>=0?'Медиа загружено и сохранено':'Медиа загружено. Сохраните новый кейс.'}catch(e){st.textContent=authError(e)}finally{$('#projectFile').value=''}};

const TYPO_SCOPES=[['home','Главная'],['state:1','Внешний экран / Услуги'],['state:2','Внешний экран / Проекты'],['state:3','Внешний экран / Компания'],['state:4','Внешний экран / Лаборатория'],['state:5','Внешний экран / Магазин'],['state:6','Внешний экран / Контакты'],['section:services','Внутри куба / Услуги'],['section:projects','Внутри куба / Проекты'],['section:company','Внутри куба / Компания'],['section:lab','Внутри куба / Лаборатория'],['section:shop','Внутри куба / Магазин'],['section:contacts','Внутри куба / Контакты'],['project-case','Открытый кейс']];
function fontPreset(name){return FONT_PRESETS.find(x=>x[0]===name)||FONT_PRESETS[0]}function ensureFont(name){const p=fontPreset(name);if(!p[2])return;const id='admin-font-'+name.toLowerCase().replace(/[^a-z0-9]+/g,'-');if(document.getElementById(id))return;const l=document.createElement('link');l.id=id;l.rel='stylesheet';l.href=`https://fonts.googleapis.com/css2?family=${p[2]}&display=swap`;document.head.appendChild(l)}
function designSettings(){content.settings=content.settings||{};const scopes=content.settings.typographyScopes||{};return{backgroundTheme:+$('#backgroundTheme').value,backgroundIntensity:+$('#backgroundIntensity').value,cubeOpacity:+$('#cubeOpacity').value,hyperSpeed:+$('#hyperSpeed').value,mainFont:$('#mainFont').value,headingFont:$('#headingFont').value,uiFont:$('#uiFont').value,typographyScopes:scopes}}
function renderDesign(){content.settings=content.settings||{};const opts=FONT_PRESETS.map(f=>`<option value="${esc(f[0])}">${esc(f[0])}</option>`).join('');$('#mainFont').innerHTML=opts;$('#headingFont').innerHTML=opts;$('#uiFont').innerHTML=opts;$('#typographyScope').innerHTML=TYPO_SCOPES.map(s=>`<option value="${s[0]}">${s[1]}</option>`).join('');const s=content.settings;$('#backgroundTheme').value=String(Number(s.backgroundTheme)||0);$('#backgroundIntensity').value=String(Number(s.backgroundIntensity??1));$('#cubeOpacity').value=String(Number(s.cubeOpacity??.20));$('#hyperSpeed').value=String(Number(s.hyperSpeed??1));$('#mainFont').value=s.mainFont||'Arial';$('#headingFont').value=s.headingFont||s.mainFont||'Arial';$('#uiFont').value=s.uiFont||s.mainFont||'Arial';syncDesignOutputs();loadTypographyScope();updateFontPreview();setTimeout(sendDesignPreview,500)}
function syncDesignOutputs(){$('#backgroundIntensityOut').textContent=(+$('#backgroundIntensity').value).toFixed(2);$('#cubeOpacityOut').textContent=(+$('#cubeOpacity').value).toFixed(2);$('#hyperSpeedOut').textContent=(+$('#hyperSpeed').value).toFixed(2)}
function loadTypographyScope(){content.settings=content.settings||{};content.settings.typographyScopes=content.settings.typographyScopes||{};const key=$('#typographyScope').value||'home',v={...DEFAULT_TYPO,...(content.settings.typographyScopes[key]||{})};$('#headingSize').value=v.headingSize;$('#bodySize').value=v.bodySize;$('#lineHeight').value=v.lineHeight;$('#letterSpacing').value=v.letterSpacing;$('#textAlign').value=v.align;$('#typographyScopeNote').textContent=TYPO_SCOPES.find(x=>x[0]===key)?.[1]||key;syncTypographyOutputs()}
function syncTypographyOutputs(){$('#headingSizeOut').textContent=`${+$('#headingSize').value} px`;$('#bodySizeOut').textContent=`${+$('#bodySize').value} px`;$('#lineHeightOut').textContent=(+$('#lineHeight').value).toFixed(2);$('#letterSpacingOut').textContent=`${(+$('#letterSpacing').value).toFixed(2)} em`}
function writeTypographyScope(){content.settings=content.settings||{};content.settings.typographyScopes=content.settings.typographyScopes||{};content.settings.typographyScopes[$('#typographyScope').value]={headingSize:+$('#headingSize').value,bodySize:+$('#bodySize').value,lineHeight:+$('#lineHeight').value,letterSpacing:+$('#letterSpacing').value,align:$('#textAlign').value};syncTypographyOutputs()}
function updateFontPreview(){const n=$('#headingFont').value||$('#mainFont').value||'Arial';ensureFont(n);$('#fontPreview').style.fontFamily=fontPreset(n)[1]}
function sendDesignPreview(){if(!content)return;writeTypographyScope();const settings=designSettings();const frame=$('#sitePreview');try{frame.contentWindow?.postMessage({type:'cube4d-admin-preview',settings},location.origin)}catch(_){}syncDesignOutputs();updateFontPreview()}
['backgroundTheme','backgroundIntensity','cubeOpacity','hyperSpeed','mainFont','headingFont','uiFont'].forEach(id=>$('#'+id).addEventListener('input',sendDesignPreview));
['headingSize','bodySize','lineHeight','letterSpacing','textAlign'].forEach(id=>$('#'+id).addEventListener('input',()=>{writeTypographyScope();sendDesignPreview()}));
$('#typographyScope').onchange=()=>{loadTypographyScope();sendDesignPreview()};
$('#resetTypography').onclick=()=>{content.settings=content.settings||{};content.settings.typographyScopes=content.settings.typographyScopes||{};delete content.settings.typographyScopes[$('#typographyScope').value];loadTypographyScope();sendDesignPreview()};
$('#sitePreview').addEventListener('load',()=>setTimeout(sendDesignPreview,250));$('#reloadPreview').onclick=()=>{$('#sitePreview').src='/?adminPreview='+Date.now()};
$('#saveDesign').onclick=async()=>{const st=$('#designStatus');st.textContent='Сохранение…';try{writeTypographyScope();const settings=designSettings();const j=await api('save_settings',formJson(settings));content.settings={...(content.settings||{}),...(j.settings||settings)};st.textContent='Сохранено';sendDesignPreview()}catch(e){st.textContent=authError(e)}};

$('#previewToggle').onclick=()=>{const d=$('#previewDrawer');d.classList.toggle('open');if(d.classList.contains('open'))sendDesignPreview()};
$('#closePreview').onclick=()=>$('#previewDrawer').classList.remove('open');
$$('[data-preview-mode]').forEach(b=>b.onclick=()=>{$$('[data-preview-mode]').forEach(x=>x.classList.toggle('active',x===b));$('#previewFrameWrap').classList.toggle('mobile',b.dataset.previewMode==='mobile')});
boot();
</script>
</body>
</html>
